1	<!DOCTYPE html>
2	<html lang="en">
3	<head>
4	<meta charset="utf-8">
5	<meta name="viewport" content="width=device-width, initial-scale=1">
6	<title>Calculator</title>
7	<style>
8	  * { box-sizing: border-box; }
9	  body {
10	    margin: 0;
11	    min-height: 100vh;
12	    display: flex;
13	    align-items: center;
14	    justify-content: center;
15	    background: #eef0f3;
16	    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
17	  }
18	  .calc {
19	    width: 300px;
20	    padding: 16px;
21	    background: #1f2329;
22	    border-radius: 16px;
23	    box-shadow: 0 10px 30px rgba(0, 0, 0, 0.25);
24	  }
25	  .display {
26	    height: 72px;
27	    margin-bottom: 12px;
28	    padding: 0 12px;
29	    display: flex;
30	    align-items: center;
31	    justify-content: flex-end;
32	    background: #111418;
33	    color: #fff;
34	    font-size: 40px;
35	    border-radius: 10px;
36	    overflow: hidden;
37	    white-space: nowrap;
38	  }
39	  .keys {
40	    display: grid;
41	    grid-template-columns: repeat(4, 1fr);
42	    gap: 8px;
43	  }
44	  button {
45	    height: 56px;
46	    border: 0;
47	    border-radius: 10px;
48	    background: #3a3f47;
49	    color: #fff;
50	    font-size: 22px;
51	    cursor: pointer;
52	  }
53	  button:active { filter: brightness(1.3); }
54	  button.op { background: #f0a030; }
55	  button.clear { background: #a5a5a5; color: #111; }
56	  button.equals { background: #3c8cf0; }
57	  button.wide { grid-column: span 2; }
58	</style>
59	</head>
60	<body>
61	<div class="calc">
62	  <div class="display" data-testid="calc-display" data-value="0" data-error="false" aria-live="polite">0</div>
63	  <div class="keys">
64	    <button class="clear wide" data-testid="key-lparen" aria-label="open group">(</button>
65	    <button class="clear wide" data-testid="key-rparen" aria-label="close group">)</button>
66	
67	    <button class="clear" data-testid="key-clear">AC</button>
68	    <button class="clear" data-testid="key-sign" aria-label="change sign">±</button>
69	    <button class="clear" data-testid="key-percent" aria-label="percent">%</button>
70	    <button class="op" data-testid="key-div" aria-label="divide">÷</button>
71	
72	    <button data-testid="key-7">7</button>
73	    <button data-testid="key-8">8</button>
74	    <button data-testid="key-9">9</button>
75	    <button class="op" data-testid="key-mul" aria-label="multiply">×</button>
76	
77	    <button data-testid="key-4">4</button>
78	    <button data-testid="key-5">5</button>
79	    <button data-testid="key-6">6</button>
80	    <button class="op" data-testid="key-sub" aria-label="subtract">−</button>
81	
82	    <button data-testid="key-1">1</button>
83	    <button data-testid="key-2">2</button>
84	    <button data-testid="key-3">3</button>
85	    <button class="op" data-testid="key-add" aria-label="add">+</button>
86	
87	    <button class="wide" data-testid="key-0">0</button>
88	    <button data-testid="key-dot" aria-label="decimal point">.</button>
89	    <button class="equals" data-testid="key-equals" aria-label="equals">=</button>
90	  </div>
91	</div>
92	<script>
93	(function () {
94	  var display = document.querySelector('[data-testid="calc-display"]');
95	
96	  // entry: string being typed, or null when no entry is in progress.
97	  // value: the number currently shown when not typing (result or stored operand).
98	  // derived: true when entry came from ± or % on a computed number rather than typing;
99	  // it is shown formatted, and the next digit starts a new entry.
100	
101	  // groups: stack of the outer { stored, op } saved by each open "(".
102	  var state;
103	
104	  // [REQ-001] [REQ-004] [REQ-005]
105	  function reset() {
106	    state = { entry: null, value: 0, stored: null, op: null, error: false, derived: false, groups: [] };
107	  }
108	
109	  // [REQ-001]
110	  function compute(a, op, b) {
111	    var r;
112	    if (op === 'add') r = a + b;
113	    else if (op === 'sub') r = a - b;
114	    else if (op === 'mul') r = a * b;
115	    else if (op === 'div') r = a / b;
116	    // [REQ-003] Division by zero (or any non-finite result) becomes the error state.
117	    // The result is never rounded here: rounding is presentation only.
118	    if (!isFinite(r)) return NaN;
119	    return r;
120	  }
121	
122	  // [REQ-003]
123	  // Presentation only: at most 10 significant digits, no trailing zeros, no
124	  // thousands separators, exponential only for |n| >= 1e10 or |n| < 1e-9.
125	  function formatNumber(n) {
126	    if (n === 0) return '0';
127	    var r = Number(n.toPrecision(10));
128	    var abs = Math.abs(r);
129	    if (abs >= 1e10 || abs < 1e-9) {
130	      return r.toExponential(9).replace(/\.?0+e/, 'e');
131	    }
132	    var exp = parseInt(r.toExponential().split('e')[1], 10);
133	    var s = r.toFixed(Math.max(0, 9 - exp));
134	    return s.indexOf('.') === -1 ? s : s.replace(/\.?0+$/, '');
135	  }
136	
137	  // [REQ-001] [REQ-003]
138	  function render() {
139	    display.setAttribute('data-error', state.error ? 'true' : 'false');
140	    if (state.error) {
141	      display.textContent = 'Error';
142	      display.setAttribute('data-value', String(NaN));
143	      return;
144	    }
145	    if (state.entry !== null) {
146	      display.textContent = state.derived ? formatNumber(Number(state.entry)) : state.entry;
147	      display.setAttribute('data-value', String(Number(state.entry)));
148	    } else {
149	      display.textContent = formatNumber(state.value);
150	      display.setAttribute('data-value', String(state.value));
151	    }
152	  }
153	
154	  // [REQ-001]
155	  function inputDigit(d) {
156	    if (state.derived) { state.entry = null; state.derived = false; }
157	    if (state.entry === null || state.entry === '0') state.entry = d;
158	    else state.entry += d;
159	  }
160	
161	  // [REQ-001]
162	  function inputDot() {
163	    if (state.derived) { state.entry = null; state.derived = false; }
164	    if (state.entry === null) state.entry = '0.';
165	    else if (state.entry.indexOf('.') === -1) state.entry += '.';
166	  }
167	
168	  // [REQ-004]
169	  // ± and % act on the current entry. With no entry in progress, the number on
170	  // the display becomes the entry, so it can still feed the pending operation.
171	  function inputSign() {
172	    if (state.entry === null) { state.entry = String(state.value); state.derived = true; }
173	    state.entry = state.entry.charAt(0) === '-' ? state.entry.slice(1) : '-' + state.entry;
174	  }
175	
176	  // [REQ-004]
177	  function inputPercent() {
178	    var n = state.entry === null ? state.value : Number(state.entry);
179	    state.entry = String(n / 100);
180	    state.derived = true;
181	  }
182	
183	  // [REQ-001] [REQ-002]
184	  // Immediate execution: an operator key first finishes the waiting operation,
185	  // strictly left to right, with no precedence, so the display always shows a
186	  // real running result. 2 + 3 × 4 = 20.
187	  function inputOperator(op) {
188	    if (state.error) return;
189	    if (state.entry !== null) {
190	      var n = Number(state.entry);
191	      state.entry = null;
192	      state.derived = false;
193	      if (state.op !== null && state.stored !== null) {
194	        state.value = compute(state.stored, state.op, n);
195	        if (isNaN(state.value)) { state.error = true; return; }
196	      } else {
197	        state.value = n;
198	      }
199	    }
200	    state.stored = state.value;
201	    state.op = op;
202	  }
203	
204	  // [REQ-005]
205	  // "(" starts a group only where a new number could start. It saves the waiting
206	  // operation and begins a fresh calculation inside the group.
207	  function inputOpenGroup() {
208	    if (state.entry !== null) return;
209	    state.groups.push({ stored: state.stored, op: state.op });
210	    state.stored = null;
211	    state.op = null;
212	  }
213	
214	  // [REQ-005]
215	  // ")" finishes the calculation inside the group, left to right, and hands its
216	  // result back as the entry for the saved outer operation.
217	  function inputCloseGroup() {
218	    if (state.groups.length === 0 || state.entry === null) return;
219	    var n = Number(state.entry);
220	    if (state.op !== null && state.stored !== null) {
221	      n = compute(state.stored, state.op, n);
222	      if (isNaN(n)) { state.error = true; return; }
223	    }
224	    var outer = state.groups.pop();
225	    state.stored = outer.stored;
226	    state.op = outer.op;
227	    state.value = n;
228	    state.entry = String(n);
229	    state.derived = true;
230	  }
231	
232	  // [REQ-001] [REQ-005]
233	  function inputEquals() {
234	    // Groups still open are closed first.
235	    while (!state.error && state.groups.length > 0 && state.entry !== null) inputCloseGroup();
236	    if (state.error || state.op === null || state.entry === null) return;
237	    var result = compute(state.stored, state.op, Number(state.entry));
238	    state.entry = null;
239	    state.derived = false;
240	    state.op = null;
241	    state.stored = null;
242	    if (isNaN(result)) { state.error = true; return; }
243	    state.value = result;
244	  }
245	
246	  // [REQ-001] [REQ-003] [REQ-004] [REQ-005]
247	  function press(key) {
248	    // In the error state every key except clear is ignored.
249	    if (state.error && key !== 'clear') return;
250	    if (/^[0-9]$/.test(key)) inputDigit(key);
251	    else if (key === 'dot') inputDot();
252	    else if (key === 'sign') inputSign();
253	    else if (key === 'percent') inputPercent();
254	    else if (key === 'add' || key === 'sub' || key === 'mul' || key === 'div') inputOperator(key);
255	    else if (key === 'lparen') inputOpenGroup();
256	    else if (key === 'rparen') inputCloseGroup();
257	    else if (key === 'equals') inputEquals();
258	    else if (key === 'clear') reset();
259	    render();
260	  }
261	
262	  document.querySelector('.keys').addEventListener('click', function (e) {
263	    var btn = e.target.closest('button[data-testid^="key-"]');
264	    if (btn) press(btn.getAttribute('data-testid').slice(4));
265	  });
266	
267	  var keyMap = { '.': 'dot', ',': 'dot', '+': 'add', '-': 'sub', '*': 'mul', 'x': 'mul',
268	    '/': 'div', '%': 'percent', '(': 'lparen', ')': 'rparen', '=': 'equals', 'Enter': 'equals', 'Escape': 'clear', 'c': 'clear', 'C': 'clear' };
269	  document.addEventListener('keydown', function (e) {
270	    if (e.metaKey || e.ctrlKey || e.altKey) return;
271	    var key = /^[0-9]$/.test(e.key) ? e.key : keyMap[e.key];
272	    if (key) {
273	      e.preventDefault();
274	      press(key);
275	    }
276	  });
277	
278	  reset();
279	  render();
280	})();
281	</script>
282	</body>
283	</html>
